/** Set these once from the app with R.font families (Plus Jakarta Sans, Inter, JetBrains Mono). */
object CpFonts {
    var display: FontFamily = FontFamily.SansSerif
    var text: FontFamily = FontFamily.SansSerif
    var mono: FontFamily = FontFamily.Monospace
}

object CpType {
    val displayLg: TextStyle get() = TextStyle(fontFamily = CpFonts.display, fontSize = 40.sp, lineHeight = 48.sp, fontWeight = FontWeight.W800, letterSpacing = (-0.02).em)
    val display: TextStyle get() = TextStyle(fontFamily = CpFonts.display, fontSize = 32.sp, lineHeight = 40.sp, fontWeight = FontWeight.W800, letterSpacing = (-0.02).em)
    val h1: TextStyle get() = TextStyle(fontFamily = CpFonts.display, fontSize = 28.sp, lineHeight = 36.sp, fontWeight = FontWeight.W700, letterSpacing = (-0.015).em)
    val h2: TextStyle get() = TextStyle(fontFamily = CpFonts.display, fontSize = 24.sp, lineHeight = 32.sp, fontWeight = FontWeight.W700, letterSpacing = (-0.01).em)
    val h3: TextStyle get() = TextStyle(fontFamily = CpFonts.display, fontSize = 20.sp, lineHeight = 28.sp, fontWeight = FontWeight.W700, letterSpacing = (-0.005).em)
    val title: TextStyle get() = TextStyle(fontFamily = CpFonts.text, fontSize = 17.sp, lineHeight = 24.sp, fontWeight = FontWeight.W600, letterSpacing = (-0.01).em)
    val bodyLg: TextStyle get() = TextStyle(fontFamily = CpFonts.text, fontSize = 16.sp, lineHeight = 24.sp, fontWeight = FontWeight.W400, letterSpacing = (-0.005).em)
    val body: TextStyle get() = TextStyle(fontFamily = CpFonts.text, fontSize = 14.sp, lineHeight = 20.sp, fontWeight = FontWeight.W400, letterSpacing = (0).em)
    val bodyStrong: TextStyle get() = TextStyle(fontFamily = CpFonts.text, fontSize = 14.sp, lineHeight = 20.sp, fontWeight = FontWeight.W600, letterSpacing = (0).em)
    val label: TextStyle get() = TextStyle(fontFamily = CpFonts.text, fontSize = 15.sp, lineHeight = 20.sp, fontWeight = FontWeight.W600, letterSpacing = (-0.005).em)
    val labelSm: TextStyle get() = TextStyle(fontFamily = CpFonts.text, fontSize = 13.sp, lineHeight = 16.sp, fontWeight = FontWeight.W600, letterSpacing = (0).em)
    val caption: TextStyle get() = TextStyle(fontFamily = CpFonts.text, fontSize = 12.sp, lineHeight = 16.sp, fontWeight = FontWeight.W500, letterSpacing = (0.005).em)
    val overline: TextStyle get() = TextStyle(fontFamily = CpFonts.text, fontSize = 11.sp, lineHeight = 16.sp, fontWeight = FontWeight.W600, letterSpacing = (0.06).em)
    val amountXl: TextStyle get() = TextStyle(fontFamily = CpFonts.display, fontSize = 40.sp, lineHeight = 48.sp, fontWeight = FontWeight.W800, letterSpacing = (-0.02).em, fontFeatureSettings = "tnum")
    val amount: TextStyle get() = TextStyle(fontFamily = CpFonts.display, fontSize = 24.sp, lineHeight = 32.sp, fontWeight = FontWeight.W700, letterSpacing = (-0.01).em, fontFeatureSettings = "tnum")
    val code: TextStyle get() = TextStyle(fontFamily = CpFonts.mono, fontSize = 13.sp, lineHeight = 20.sp, fontWeight = FontWeight.W400, letterSpacing = (0).em)
}

