object CpMotion {
    const val INSTANT = 100
    const val FAST = 150
    const val BASE = 200
    const val MODERATE = 300
    const val SLOW = 450
    const val DELIBERATE = 600
    const val SHIMMER = 1400
    val Standard = CubicBezierEasing(0.2f, 0f, 0f, 1f)
    val Enter = CubicBezierEasing(0f, 0f, 0f, 1f)
    val Exit = CubicBezierEasing(0.3f, 0f, 1f, 1f)
    val Emphasized = CubicBezierEasing(0.3f, 0f, 0f, 1f)
    val Linear = CubicBezierEasing(0f, 0f, 1f, 1f)
    fun <T> snappySpring() = spring<T>(dampingRatio = 0.86f, stiffness = 438.6f)
    fun <T> smoothSpring() = spring<T>(dampingRatio = 1f, stiffness = 195.0f)
    fun <T> bouncySpring() = spring<T>(dampingRatio = 0.7f, stiffness = 157.9f)
    const val PRESSED_SCALE = 0.97f
    const val DISABLED_ALPHA = 0.4f
}

