}

val CpBrandGradient = Brush.horizontalGradient(0f to Color(0xFF381987), 1f to Color(0xFF01AAA5))

/** The product's logo gradient (left -> right). */
fun cpProductGradient(product: CpProduct): Brush = when (product) {
    CpProduct.CONSUMER -> Brush.horizontalGradient(listOf(Color(0xFF381987), Color(0xFF01AAA5)))
    CpProduct.SELLER -> Brush.horizontalGradient(listOf(Color(0xFFF65F4F), Color(0xFFFDA73B)))
    CpProduct.DELIVERY -> Brush.horizontalGradient(listOf(Color(0xFF750C6F), Color(0xFFED0066)))
    CpProduct.CONSOLE -> Brush.horizontalGradient(listOf(Color(0xFF3C2566), Color(0xFF9478CB)))
    CpProduct.EVENTS -> Brush.horizontalGradient(listOf(Color(0xFF5F3A9F), Color(0xFF3966E6)))
    CpProduct.KAMPUS -> Brush.horizontalGradient(listOf(Color(0xFF2450CC), Color(0xFF38BDF8)))
    CpProduct.MENU -> Brush.horizontalGradient(listOf(Color(0xFFE1517D), Color(0xFFED7325)))
}
